mapper.select:
SELECT ranked.session_id, ranked.mem_obj_type, ranked.mem_obj_id, ranked.mem_name, ranked.avatar FROM ( SELECT member.session_id, member.mem_obj_type, member.mem_obj_id, COALESCE( NULLIF(TRIM(CASE WHEN member.mem_obj_type = 'AGENT' THEN resource.resource_name WHEN member.mem_obj_type = 'USER' THEN user_info.user_name END), ''), NULLIF(TRIM(member.mem_name), '') ) AS mem_name, resource.avatar, ROW_NUMBER() OVER ( PARTITION BY member.session_id ORDER BY CASE WHEN member.mem_obj_type = 'AGENT' THEN 3 WHEN member.user_role = 'OWNER' THEN 0 WHEN member.user_role = 'ADMIN' THEN 1 ELSE 2 END, member.byai_session_member_id ASC ) AS member_row_num FROM byai_session_member member LEFT JOIN ss_resource resource ON member.mem_obj_type = 'AGENT' AND resource.resource_id = member.mem_obj_id LEFT JOIN po_users user_info ON member.mem_obj_type = 'USER' AND user_info.user_id = member.mem_obj_id WHERE member.session_id IN
#{sessionId}
) ranked WHERE ranked.member_row_num <= #{memberLimit} ORDER BY ranked.session_id, ranked.member_row_num

mapper.update:
UPDATE byai_session_member
SET last_read_message_id = #{messageId},
    last_read_time = #{readTime}
WHERE byai_session_member_id = #{memberId}
  AND (last_read_message_id IS NULL OR last_read_message_id < #{messageId})
